fn capability_grant_problem_example_1() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_31();
    let role: types::RoleId = types::RoleId("editor".to_string());
    let name: String = "content-edit".to_string();
    let want_: Option<String> = None;
    assert_eq!(capability_grant_problem(&schema, &role, &name), want_);
}

/// A capability of the product form nobody declared.
#[test]
fn capability_grant_problem_example_2() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_31();
    let role: types::RoleId = types::RoleId("editor".to_string());
    let name: String = "other__thing".to_string();
    let want_: Option<String> = Some(
        "capability other__thing is neither a platform capability nor declared in the tenant"
            .to_string(),
    );
    assert_eq!(capability_grant_problem(&schema, &role, &name), want_);
}

/// A role of the tenant's own may grant a declared capability.
#[test]
fn capability_grant_problem_example_3() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_31();
    let role: types::RoleId = types::RoleId("editor".to_string());
    let name: String = "member_tiers__promote".to_string();
    let want_: Option<String> = None;
    assert_eq!(capability_grant_problem(&schema, &role, &name), want_);
}

/// A role of the same product.
#[test]
fn capability_grant_problem_example_4() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_31();
    let role: types::RoleId = types::RoleId("member_tiers__host".to_string());
    let name: String = "member_tiers__promote".to_string();
    let want_: Option<String> = None;
    assert_eq!(capability_grant_problem(&schema, &role, &name), want_);
}

/// A role of another product may not.
#[test]
fn capability_grant_problem_example_5() {
    let schema: types::TenantSchema = fixture_fx_tenant_schema_31();
    let role: types::RoleId = types::RoleId("crm__agent".to_string());
    let name: String = "member_tiers__promote".to_string();
    let want_: Option<String> = Some(
        "capability member_tiers__promote belongs to product member_tiers and role crm__agent to product crm"
            .to_string(),
    );
    assert_eq!(capability_grant_problem(&schema, &role, &name), want_);
}

/// A name whose namespace is empty is declared but has none.
#[test]
fn capability_grant_problem_example_6() {
    let schema: types::TenantSchema = {
        let mut fixture = fixture_fx_tenant_schema_6();
        fixture.capabilities = Some(std::collections::BTreeMap::from([(
            types::CapabilityName("__x".to_string()),
            types::CapabilityDef {
                id: types::CapabilityName("__x".to_string()),
                name: "X".to_string(),
                description: "d".to_string(),
            },
        )]));
        fixture
    };
    let role: types::RoleId = types::RoleId("crm__agent".to_string());
    let name: String = "__x".to_string();
    let want_: Option<String> = None;
    assert_eq!(capability_grant_problem(&schema, &role, &name), want_);
}

