/// Example 2 of `capability-problems`.
#[test]
fn capability_problems_example_2() {
    let schema: types::TenantSchema = {
        let mut fixture = fixture_fx_tenant_schema_31();
        fixture
            .capabilities
            .as_mut()
            .expect("the fixture value is present")
            .get_mut(&types::CapabilityName("member_tiers__promote".to_string()))
            .expect("the fixture has the key")
            .description = "d".to_string();
        fixture
            .capabilities
            .as_mut()
            .expect("the fixture value is present")
            .get_mut(&types::CapabilityName("member_tiers__promote".to_string()))
            .expect("the fixture has the key")
            .name = "Name".to_string();
        fixture
    };
    let want_: Vec<String> = Vec::new();
    assert_eq!(capability_problems(&schema), Ok(want_));
}

/// Example 3 of `capability-problems`.
#[test]
fn capability_problems_example_3() {
    let schema: types::TenantSchema = {
        let mut fixture = fixture_fx_tenant_schema_6();
        fixture.capabilities = Some(std::collections::BTreeMap::from([
            (
                types::CapabilityName("Bad".to_string()),
                types::CapabilityDef {
                    id: types::CapabilityName("Bad".to_string()),
                    name: "Name".to_string(),
                    description: "d".to_string(),
                },
            ),
            (
                types::CapabilityName("a__b".to_string()),
                types::CapabilityDef {
                    id: types::CapabilityName("a__b".to_string()),
                    name: "Name".to_string(),
                    description: "d".to_string(),
                },
            ),
            (
                types::CapabilityName("c__d".to_string()),
                types::CapabilityDef {
                    id: types::CapabilityName("c__d".to_string()),
                    name: " ".to_string(),
                    description: "d".to_string(),
                },
            ),
        ]));
        fixture
    };
    let want_: Vec<String> = vec![
        "capability Bad: an id is a namespace and a name of lower-case letters, digits and underscores, joined by two underscores"
        .to_string(), "capability c__d: a capability needs a name".to_string()
    ];
    assert_eq!(capability_problems(&schema), Ok(want_));
}

/// Example 4 of `capability-problems`.
#[test]
fn capability_problems_example_4() {
    let schema: types::TenantSchema = {
        let mut fixture = fixture_fx_tenant_schema_6();
        fixture.capabilities = Some(std::collections::BTreeMap::from([(
            types::CapabilityName("other__x".to_string()),
            types::CapabilityDef {
                id: types::CapabilityName("a__b".to_string()),
                name: "Name".to_string(),
                description: "d".to_string(),
            },
        )]));
        fixture
    };
    let want_: Vec<String> = vec!["capability a__b: held under the key other__x".to_string()];
    assert_eq!(capability_problems(&schema), Ok(want_));
}

