/// Example 1 of `capability-def-problems`.
#[test]
fn capability_def_problems_example_1() {
    let key: types::CapabilityName = types::CapabilityName("a__b".to_string());
    let d: types::CapabilityDef = types::CapabilityDef {
        id: types::CapabilityName("a__b".to_string()),
        name: "Name".to_string(),
        description: "d".to_string(),
    };
    let want_: Vec<String> = Vec::new();
    assert_eq!(capability_def_problems(&key, &d), Ok(want_));
}

/// Example 2 of `capability-def-problems`.
#[test]
fn capability_def_problems_example_2() {
    let key: types::CapabilityName = types::CapabilityName("other".to_string());
    let d: types::CapabilityDef = types::CapabilityDef {
        id: types::CapabilityName("a__b".to_string()),
        name: "Name".to_string(),
        description: "d".to_string(),
    };
    let want_: Vec<String> = vec!["capability a__b: held under the key other".to_string()];
    assert_eq!(capability_def_problems(&key, &d), Ok(want_));
}

/// Example 3 of `capability-def-problems`.
#[test]
fn capability_def_problems_example_3() {
    let key: types::CapabilityName = types::CapabilityName("Bad".to_string());
    let d: types::CapabilityDef = types::CapabilityDef {
        id: types::CapabilityName("Bad".to_string()),
        name: "Name".to_string(),
        description: "d".to_string(),
    };
    let want_: Vec<String> = vec![
        "capability Bad: an id is a namespace and a name of lower-case letters, digits and underscores, joined by two underscores"
        .to_string()
    ];
    assert_eq!(capability_def_problems(&key, &d), Ok(want_));
}

/// Example 4 of `capability-def-problems`.
#[test]
fn capability_def_problems_example_4() {
    let key: types::CapabilityName = types::CapabilityName("a__b".to_string());
    let d: types::CapabilityDef = types::CapabilityDef {
        id: types::CapabilityName("a__b".to_string()),
        name: " ".to_string(),
        description: "d".to_string(),
    };
    let want_: Vec<String> = vec!["capability a__b: a capability needs a name".to_string()];
    assert_eq!(capability_def_problems(&key, &d), Ok(want_));
}

/// Example 1 of `capability-well-formed`.
#[test]
fn capability_well_formed_example_1() {
    let id: String = "member_tiers__promote".to_string();
    let want_: bool = true;
    assert_eq!(capability_well_formed(&id), Ok(want_));
}

/// Example 2 of `capability-well-formed`.
#[test]
fn capability_well_formed_example_2() {
    let id: String = "plain".to_string();
    let want_: bool = false;
    assert_eq!(capability_well_formed(&id), Ok(want_));
}

/// Example 3 of `capability-well-formed`.
