/// Example 2 of `ledger-change-needs`.
#[test]
fn ledger_change_needs_example_2() {
    let changes: Vec<types::SchemaChange> = vec![
        types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Unit {
            unit: types::LedgerUnit("credits".to_string()),
        }),
        types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Pool {
            pool: types::LedgerPoolName("promo".to_string()),
        }),
        types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Limit {
            unit: types::LedgerUnit("credits".to_string()),
            owner: None,
            scope: None,
        }),
        types::SchemaChange::DeclareLedgerUnit(types::LedgerUnitDecl {
            unit: types::LedgerUnit("x".to_string()),
            description: "x".to_string(),
            expiry: None,
        }),
    ];
    let want_: Vec<types::Need> = vec![
        types::Need::Ledger(types::LedgerNeed::UnitUsed {
            unit: types::LedgerUnit("credits".to_string()),
        }),
        types::Need::Ledger(types::LedgerNeed::PoolUsed {
            pool: types::LedgerPoolName("promo".to_string()),
        }),
    ];
    assert_eq!(ledger_change_needs(&changes), want_);
}

/// Setting the limit of one account asks for every limit of single accounts; setting the limit of a unit asks for nothing.
#[test]
fn ledger_change_needs_example_3() {
    let changes: Vec<types::SchemaChange> = vec![
        types::SchemaChange::SetLedgerLimit(types::LedgerLimit {
            unit: types::LedgerUnit("credits".to_string()),
            owner: Some(types::LedgerOwner::Principal {
                principal: types::PrincipalId("user:ines".to_string()),
            }),
            floor: None,
            cap: Some(types::LedgerAmount(100)),
            period_cap: None,
            period: None,
            scope: None,
        }),
        types::SchemaChange::SetLedgerLimit(types::LedgerLimit {
            unit: types::LedgerUnit("credits".to_string()),
            owner: None,
            floor: Some(types::LedgerAmount(0)),
            cap: None,
            period_cap: None,
            period: None,
            scope: None,
        }),
    ];
    let want_: Vec<types::Need> = vec![types::Need::Ledger(types::LedgerNeed::Limits)];
    assert_eq!(ledger_change_needs(&changes), want_);
}

/// Removing the limit of one account asks for that account's limit, in its scope or in none; removing the limit of a unit asks for nothing.
#[test]
fn ledger_change_needs_example_4() {
    let changes: Vec<types::SchemaChange> = vec![
        types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Limit {
            unit: types::LedgerUnit("credits".to_string()),
            owner: Some(types::LedgerOwner::Principal {
                principal: types::PrincipalId("user:ines".to_string()),
            }),
            scope: Some(types::LedgerScope("spring".to_string())),
        }),
        types::SchemaChange::RemoveLedgerDefinition(types::LedgerDefinitionRef::Limit {
            unit: types::LedgerUnit("credits".to_string()),
            owner: Some(types::LedgerOwner::Pool {
                pool: types::LedgerPoolName("promo".to_string()),
            }),
            scope: None,
        }),
    ];
    let want_: Vec<types::Need> = vec![
        types::Need::Ledger(types::LedgerNeed::Limit {
            owner: types::LedgerOwner::Principal {
                principal: types::PrincipalId("user:ines".to_string()),
            },
            unit: types::LedgerUnit("credits".to_string()),
            scope: types::LedgerScope("spring".to_string()),
        }),
        types::Need::Ledger(types::LedgerNeed::Limit {
            owner: types::LedgerOwner::Pool {
                pool: types::LedgerPoolName("promo".to_string()),
            },
            unit: types::LedgerUnit("credits".to_string()),
            scope: types::LedgerScope("".to_string()),
        }),
    ];
    assert_eq!(ledger_change_needs(&changes), want_);
}

