fn ledger_limit_step_example_5() {
    let d: types::Draft = {
        let mut fixture = fixture_fx_draft_28();
        fixture.coverage = types::Coverage::Partial(std::collections::BTreeSet::new());
        fixture
    };
    let w: types::LedgerLimitWalk = types::LedgerLimitWalk {
        evidence: Vec::new(),
        held: None,
    };
    let c: types::SchemaChange = types::SchemaChange::SetLedgerLimit(types::LedgerLimit {
        unit: types::LedgerUnit("credits".to_string()),
        owner: Some(types::LedgerOwner::Principal {
            principal: types::PrincipalId("alpha:ed".to_string()),
        }),
        floor: None,
        cap: Some(types::LedgerAmount(9)),
        period_cap: None,
        period: None,
        scope: None,
    });
    let max: u64 = 3;
    assert_eq!(
        ledger_limit_step(&d, &w, &c, max),
        Err(types::Rejection::Rejected(types::DomainError {
            kind: types::ErrorKind::InsufficientState,
            message: "the snapshot does not cover Ledger(Limits)".to_string(),
            evidence: vec![types::Check {
                rule: "coverage".to_string(),
                passed: false,
                detail: "Ledger(Limits)".to_string()
            }],
            missing: Some(types::Need::Ledger(types::LedgerNeed::Limits))
        }))
    );
}

